export default JSON.parse("{\"2.13.2\":{\"unit\":\"2.13\",\"courseId\":\"2.13.2\",\"bridge\":\"In 2.13.1 you listed the paths for one chart, each with a trigger and an action. A playbook fixes that once per setup: a card with checkable fields, built from 2.8's strategies or your plan v1 (1.6.2), and judged with 2.11.7's intervals.\",\"hook\":{\"prompt\":\"Your journal has 60 trades tagged with 9 different setup names. On average, how many trades does each setup have to be judged on?\",\"control\":{\"kind\":\"slider\",\"min\":0,\"max\":60,\"step\":0.1,\"unit\":\"trades\",\"start\":30,\"answer\":6.7,\"tolerance\":1,\"feedback\":[{\"from\":0,\"to\":5.6,\"text\":\"A few more than that: 60 ÷ 9 = 6.7 trades a setup. Still far too few.\"},{\"from\":7.8,\"to\":60,\"text\":\"Fewer than that: 60 ÷ 9 = 6.7 trades a setup. Too few to judge any of them.\"}]},\"compare\":\"You said {yours}. 60 ÷ 9 = 6.7 trades a setup: too few to judge any of them. Fewer setups, more trades each.\",\"concept\":\"sample-size\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"One card per setup\",\"text\":\"Your [[playbook]] is a set of [[setup-card|setup cards]], one per setup. A card turns 'I trade pullbacks' into rules anyone could check: when the setup is allowed, what triggers the entry, where it's wrong, how it's managed, and when you don't take it. Each card also keeps its own statistics, so you can see which setups earn their place.\"},{\"kind\":\"figure\",\"title\":\"A complete card\",\"text\":\"The LABX pullback card, field by field. Yours will say different things; the fields stay the same.\",\"figure\":{\"kind\":\"flow\",\"start\":\"name\",\"nodes\":[{\"id\":\"name\",\"text\":\"Name: LABX trend pullback, 1H chart\",\"kind\":\"end\"},{\"id\":\"regime\",\"text\":\"Regime: uptrend, the last two swing highs and lows each higher\",\"kind\":\"end\"},{\"id\":\"trigger\",\"text\":\"Trigger: the pullback holds above the last swing low\",\"kind\":\"end\"},{\"id\":\"order\",\"text\":\"Order: buy stop at the high of the pullback's lowest candle\",\"kind\":\"end\"},{\"id\":\"stop\",\"text\":\"Stop: the pullback low minus half an ATR\",\"kind\":\"end\"},{\"id\":\"manage\",\"text\":\"Targets: the previous swing high, at least 2R; then trail under new swing lows\",\"kind\":\"end\"},{\"id\":\"reentry\",\"text\":\"Re-entry: once, on a new trigger, while the last swing low holds\",\"kind\":\"end\"},{\"id\":\"notrade\",\"text\":\"No trade: a red event within 15 minutes, or the regime unclear\",\"kind\":\"end\"},{\"id\":\"quality\",\"text\":\"Quality: A at 3R or more to target, B at 2R to 3R, under 2R no trade\",\"kind\":\"end\"},{\"id\":\"evidence\",\"text\":\"Evidence: sim-tested; course grade C\",\"kind\":\"end\"},{\"id\":\"stats\",\"text\":\"Statistics: n, win rate, average R, MAE and MFE, and the interval\",\"kind\":\"end\"}],\"steps\":[\"When: the regime and the trigger, each a yes or no on the chart.\",\"Risk: order type, stop rule, targets and re-entry, all fixed before entry.\",\"When not: no-trade conditions, and a quality grade from the distance to target.\",\"Evidence and statistics: what's been tested, and the numbers so far.\"]},\"concept\":\"setup-card\"},{\"kind\":\"hotspot\",\"title\":\"The missing field\",\"prompt\":\"This card has a regime, a trigger and a target, but no invalidation. The pullback low is 56.80 and the ATR is 0.80. Tap where the card's stop belongs.\",\"chart\":{\"candles\":[{\"o\":54,\"h\":54.45,\"l\":53.8,\"c\":54.3},{\"o\":54.3,\"h\":55.05,\"l\":54.2,\"c\":54.9},{\"o\":54.9,\"h\":55.6,\"l\":54.75,\"c\":55.45},{\"o\":55.45,\"h\":56.15,\"l\":55.3,\"c\":56},{\"o\":56,\"h\":56.6,\"l\":55.85,\"c\":56.2},{\"o\":56.2,\"h\":56.35,\"l\":55.55,\"c\":55.7},{\"o\":55.7,\"h\":56.1,\"l\":55.4,\"c\":55.6},{\"o\":55.6,\"h\":56.35,\"l\":55.5,\"c\":56.15},{\"o\":56.15,\"h\":56.9,\"l\":56.05,\"c\":56.8},{\"o\":56.8,\"h\":57.55,\"l\":56.7,\"c\":57.45},{\"o\":57.45,\"h\":58.2,\"l\":57.3,\"c\":58.05},{\"o\":58.05,\"h\":58.75,\"l\":57.9,\"c\":58.6},{\"o\":58.6,\"h\":59.3,\"l\":58.3,\"c\":59.15},{\"o\":59.15,\"h\":59.6,\"l\":58.8,\"c\":59.3},{\"o\":59.3,\"h\":59.4,\"l\":58.6,\"c\":58.7},{\"o\":58.7,\"h\":58.85,\"l\":58.05,\"c\":58.15},{\"o\":58.15,\"h\":58.3,\"l\":57.5,\"c\":57.6},{\"o\":57.6,\"h\":57.75,\"l\":56.95,\"c\":57.15},{\"o\":57.15,\"h\":57.2,\"l\":56.8,\"c\":57.1}],\"layers\":[{\"kind\":\"level\",\"price\":57.2,\"role\":\"entry\",\"label\":\"Buy stop 57.20\"},{\"kind\":\"level\",\"price\":59.6,\"role\":\"target\",\"label\":\"Target 59.60\"},{\"kind\":\"marker\",\"index\":18,\"at\":\"low\",\"label\":\"56.80\"}]},\"zones\":[{\"id\":\"inside\",\"label\":\"Just under the entry, 57.00\",\"from\":56.95,\"to\":57.05,\"feedback\":\"That's inside the pullback candle's own range. Normal noise would stop you out before the idea is wrong.\"},{\"id\":\"stop\",\"label\":\"Under the pullback low, 56.40\",\"from\":56.35,\"to\":56.45},{\"id\":\"trend\",\"label\":\"Under the earlier swing low, 55.30\",\"from\":55.25,\"to\":55.35,\"feedback\":\"That's where the whole uptrend fails, not this entry. The pullback idea is already wrong under 56.80, and this stop more than doubles the risk.\"},{\"id\":\"target\",\"label\":\"The target, 59.60\",\"from\":59.55,\"to\":59.65,\"feedback\":\"That's the target, where the idea pays. The missing line is where it fails.\"}],\"answer\":\"stop\",\"correct\":\"Right: 56.80 − 0.5 × 0.80 = 56.40. Under the pullback low, the idea that the pullback holds is wrong. Without that line, every exit is decided in the moment.\",\"concept\":\"invalidation-level\"},{\"kind\":\"match\",\"title\":\"Vague or checkable?\",\"prompt\":\"A card field is useful only if two people would agree on it. Match each vague field to its checkable version.\",\"columns\":[\"Vague\",\"Checkable\"],\"pairs\":[{\"left\":\"Strong trend\",\"right\":\"Price above the rising 50 MA, with two higher lows\",\"wrong\":\"'Strong' needs a test: where price sits against a rising average, and the swing lows.\"},{\"left\":\"Good pullback\",\"right\":\"The pullback holds above the last swing low\",\"wrong\":\"'Good' needs a level the pullback must not break.\"},{\"left\":\"Enter when it turns\",\"right\":\"Buy stop at the high of the pullback's lowest candle\",\"wrong\":\"'When it turns' needs an order at a price: the turn is proven when that high is taken out.\"},{\"left\":\"Avoid news\",\"right\":\"No entry with a red event within 15 minutes\",\"wrong\":\"'Avoid news' needs a time window and an impact level from the calendar.\"},{\"left\":\"Give it room\",\"right\":\"Stop at the pullback low minus half an ATR\",\"wrong\":\"'Room' needs a distance: structure plus a share of the normal range.\"}],\"correct\":\"Each checkable field names a level, a count or a time. The card is done when no field needs your mood to read it.\",\"concept\":\"setup-card\"},{\"kind\":\"worked\",\"title\":\"Statistics per setup\",\"lines\":[\"Setup A: 32 trades, average +0.35R. Setup B: 28 trades, average −0.10R.\",\"Both spread about 1.7R a trade (standard deviation).\",\"95% interval = average ± 1.96 × 1.7 ÷ √n: ±0.59R for A, ±0.63R for B.\",\"Lowest plausible average for A: 0.35 − 0.59 = ?\"],\"ask\":{\"answer\":-0.24,\"tolerance\":0.005,\"unit\":\"R\",\"feedback\":[{\"value\":0.94,\"text\":\"That's the top of the interval. The lowest is the average minus the half-width.\"},{\"value\":-0.59,\"text\":\"That's only the half-width. Start from A's average, +0.35R.\"}],\"correct\":\"Right: −0.24R. A's interval runs from −0.24R to +0.94R, and B's from −0.73R to +0.53R. Both include zero.\"},\"after\":\"Neither setup can be judged yet: A may have no edge, B may be fine. If A kept its average and spread, its interval would clear zero only after 91 trades.\",\"concept\":\"sample-size\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"**No card, no trade.** Specialise: one or two setups, until each has about 100 trades. Nine setups over 60 trades tell you very little about any of them.\"},{\"kind\":\"fields\",\"title\":\"Your card: when to trade\",\"prompt\":\"Write a card for a setup you'd trade, from the unit 2.8 strategies or your plan v1. Make each line checkable: a level, a count, a time or a yes or no.\",\"fields\":[{\"id\":\"name\",\"label\":\"Name, market and timeframe\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. Trend pullback, LABX, 1H\",\"required\":true},{\"id\":\"regime\",\"label\":\"Regime: when the card is allowed\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. The last two swing highs and lows are each higher\",\"required\":true},{\"id\":\"trigger\",\"label\":\"Trigger and order type\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. Buy stop at the high of the pullback's lowest candle\",\"required\":true},{\"id\":\"noTrade\",\"label\":\"No-trade conditions\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. A red event within 15 minutes; regime unclear\",\"required\":true}],\"correct\":\"Saved: the 'when' half of your card. Next, the risk half.\",\"concept\":\"setup-card\"},{\"kind\":\"fields\",\"title\":\"Your card: risk and records\",\"prompt\":\"Now the risk half. The stop comes from structure or from the ATR, never from how much you'd like to lose. Every card needs an evidence line, even if it says 'untested'.\",\"fields\":[{\"id\":\"stop\",\"label\":\"Stop rule\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. The pullback low minus half an ATR\",\"required\":true},{\"id\":\"manage\",\"label\":\"Targets and management\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. Previous swing high, at least 2R; then trail under new swing lows\",\"required\":true},{\"id\":\"reentry\",\"label\":\"Re-entry rule (optional)\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. Once, on a new trigger, while the last swing low holds\"},{\"id\":\"evidence\",\"label\":\"Evidence: status and course grade\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. Untested; course grade C\",\"required\":true}],\"correct\":\"Saved. Your card's statistics start with its first tagged trade: tag every trade with the card's name, and the numbers build themselves.\",\"concept\":\"setup-card\"}],\"check\":[\"q-2.13.2-1\",\"q-2.13.2-2\",\"q-2.13.2-3\"],\"recap\":{\"takeaways\":[\"A setup card fixes regime, trigger, stop, management, re-entry and no-trade conditions before any trade.\",\"Write every field as a level, count, time or yes-or-no, so two people would agree.\",\"Judge each setup on its own trades and interval; at 30 trades, most intervals still include zero.\"],\"next\":\"Next, 2.13.3: the pre-market routine, the same short steps before every session, to catch what makes today different.\"}},\"2.13.3\":{\"unit\":\"2.13\",\"courseId\":\"2.13.3\",\"bridge\":\"In 2.13.2 each setup got a card. Before a session you still need to know whether today allows it: an event on the calendar (2.10.2), a loss limit half used (2.11.4), a changed regime. The routine checks them in order and ends in 2.13.1's scenarios.\",\"hook\":{\"prompt\":\"It's 14:50 in Bucharest, in July. US CPI comes out at 15:30 Bucharest time. You plan to open a LABX swing trade at 15:00 with a stop 0.80 away. What does a routine catch?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"now\",\"label\":\"Enter at 15:00\",\"feedback\":\"The release lands 30 minutes into the trade. Spreads can widen and price can jump past a 0.80 stop.\"},{\"id\":\"wait\",\"label\":\"Wait until after the release and normal spreads\",\"feedback\":\"Right. The routine reads the calendar first, so the release is known before the order.\"},{\"id\":\"half\",\"label\":\"Enter at half size\",\"feedback\":\"Acceptable if your plan's news rule says so. Without a written rule, it's a decision made in the moment.\"}],\"answer\":\"wait\"},\"compare\":\"You chose “{yours}”. A routine reads the calendar before any order: CPI at 15:30 is 30 minutes after your entry. Wait, or follow your written news rule.\",\"concept\":\"pre-market-routine\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"Same steps, every session\",\"text\":\"A [[pre-market-routine|pre-market routine]] is the same short sequence before every session, about ten minutes. It doesn't find trades. It finds what's different today: an event on the calendar, a limit half used, a regime that no longer fits your card, or a trader who slept four hours. It does this before the first order, while changing the plan costs nothing.\"},{\"kind\":\"order\",\"title\":\"The routine\",\"prompt\":\"Put the eight steps in order: first you, then the market, then your plan for it, and your risk last.\",\"items\":[\"Readiness check: sleep, stress, health\",\"What happened overnight\",\"The calendar: today's events and their times\",\"A regime label for each market you trade\",\"Key levels\",\"Two or three if-then scenarios\",\"Watchlist: which cards could trigger today\",\"Maximum risk for the day, and the open risk you already carry\"],\"wrong\":\"Start with yourself: a failed readiness check changes everything after it. Then the facts, then the plan, and the risk limit last.\",\"explain\":\"You first, because a failed readiness check lowers the risk for everything after it. Then the facts, then your plan for them, and the day's risk last, sized to what you found.\",\"concept\":\"pre-market-routine\"},{\"kind\":\"hotspot\",\"title\":\"Session start\",\"prompt\":\"14:50, your session-start screen: today's 30-minute LABX candles from 10:00, yesterday's high and low, and the calendar. Tap the item that changes today's plan.\",\"chart\":{\"candles\":[{\"o\":60.05,\"h\":60.2,\"l\":59.95,\"c\":60.15},{\"o\":60.15,\"h\":60.3,\"l\":60.1,\"c\":60.25},{\"o\":60.25,\"h\":60.35,\"l\":60.15,\"c\":60.2},{\"o\":60.2,\"h\":60.25,\"l\":60.05,\"c\":60.1},{\"o\":60.1,\"h\":60.15,\"l\":59.95,\"c\":60},{\"o\":60,\"h\":60.1,\"l\":59.9,\"c\":60.05},{\"o\":60.05,\"h\":60.15,\"l\":59.95,\"c\":60.1},{\"o\":60.1,\"h\":60.2,\"l\":60,\"c\":60.15},{\"o\":60.15,\"h\":60.25,\"l\":60.05,\"c\":60.1},{\"o\":60.1,\"h\":60.2,\"l\":60.05,\"c\":60.1},{\"o\":60.1,\"h\":60.15,\"l\":60,\"c\":60.05},{\"o\":60.05,\"h\":60.7,\"l\":59.55,\"c\":59.7},{\"o\":59.7,\"h\":59.95,\"l\":59.5,\"c\":59.85},{\"o\":59.85,\"h\":60,\"l\":59.7,\"c\":59.9}],\"visible\":10,\"range\":[59.4,60.8],\"layers\":[{\"kind\":\"level\",\"price\":60.4,\"role\":\"resistance\",\"label\":\"Yesterday's high 60.40\"},{\"kind\":\"level\",\"price\":59.8,\"role\":\"support\",\"label\":\"Yesterday's low 59.80\"},{\"kind\":\"marker\",\"index\":11,\"price\":60.6,\"label\":\"15:30 US CPI\",\"role\":\"down\"}]},\"zones\":[{\"id\":\"high\",\"label\":\"Yesterday's high, 60.40\",\"index\":3,\"price\":60.4,\"feedback\":\"A key level for your scenarios, but it was there yesterday too. Look for what's new today.\"},{\"id\":\"low\",\"label\":\"Yesterday's low, 59.80\",\"index\":4,\"price\":59.8,\"feedback\":\"A key level for your scenarios, but it was there yesterday too. Look for what's new today.\"},{\"id\":\"now\",\"label\":\"Price now, 60.10\",\"index\":9,\"price\":60.1,\"feedback\":\"That's where price is. The plan changes because of what's scheduled, not where price sits.\"},{\"id\":\"cpi\",\"label\":\"US CPI at 15:30\",\"index\":11,\"price\":60.6}],\"answer\":\"cpi\",\"correct\":\"Right. A high-impact release 30 minutes after your planned entry changes the plan: no new orders until it's out and the spread is back to 0.10.\",\"concept\":\"pre-market-routine\"},{\"kind\":\"explain\",\"title\":\"Readiness first\",\"text\":\"The first step is your plan's [[fit-to-trade]] line: sleep, stress, illness. If it fails, the routine still runs, but at the risk your plan sets for those days: half, zero, or the simulator only. Tired traders rarely feel tired at the moment of decision. The check is there because the feeling isn't.\"},{\"kind\":\"match\",\"title\":\"What each step prevents\",\"prompt\":\"Each step exists to catch one mistake before it happens. Match them.\",\"columns\":[\"Step\",\"Mistake it prevents\"],\"pairs\":[{\"left\":\"The calendar\",\"right\":\"Trading into a scheduled release\",\"wrong\":\"The calendar is where scheduled releases show up, with their times.\"},{\"left\":\"Maximum risk for the day\",\"right\":\"Breaking the daily loss limit\",\"wrong\":\"Setting today's maximum loss in advance is what keeps the daily limit intact.\"},{\"left\":\"The regime label\",\"right\":\"Using a range card in a trend\",\"wrong\":\"The regime label decides which cards are allowed today.\"},{\"left\":\"Key levels\",\"right\":\"Chasing an entry far from any level\",\"wrong\":\"Levels marked in advance tell you where entries belong, so you don't buy in the middle of a run.\"},{\"left\":\"Readiness check\",\"right\":\"Trading full size on four hours' sleep\",\"wrong\":\"Readiness is about you: sleep, stress, health.\"}],\"correct\":\"Five steps, five mistakes caught before the first order. That's the whole job of the routine.\",\"concept\":\"pre-market-routine\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"The routine ends in writing: the regime, two levels, your if-then scenarios and today's maximum risk. The evidence is grade B to C (research on planning, one qualitative study of traders), so judge it by the errors it catches in your own journal.\"},{\"kind\":\"fields\",\"title\":\"Today's session start\",\"prompt\":\"Run it for this session: LABX at 60.10, yesterday's range 59.80–60.40, US CPI at 15:30. Your plan's daily limit is −3R. Write what the routine produces.\",\"fields\":[{\"id\":\"regime\",\"label\":\"Regime label\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. Range: inside yesterday's 59.80–60.40, no clear trend\",\"required\":true},{\"id\":\"levels\",\"label\":\"Two key levels\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. 60.40 yesterday's high; 59.80 yesterday's low\",\"required\":true},{\"id\":\"scenarios\",\"label\":\"Two or three if-then scenarios, one for the 15:30 release\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. If CPI is within 15 minutes, then no new orders until the spread is back to 0.10\",\"required\":true},{\"id\":\"fit\",\"label\":\"Readiness checks passed: __ of 3\",\"kind\":\"stepper\",\"min\":0,\"max\":3,\"step\":1,\"default\":3},{\"id\":\"dayRisk\",\"label\":\"Maximum loss today: __R\",\"kind\":\"stepper\",\"min\":0.5,\"max\":5,\"step\":0.5,\"unit\":\"R\",\"default\":4}],\"valid\":{\"all\":[{\"field\":\"dayRisk\",\"lte\":3},{\"any\":[{\"field\":\"fit\",\"eq\":3},{\"field\":\"dayRisk\",\"lte\":1.5}]}]},\"feedback\":[{\"when\":{\"field\":\"dayRisk\",\"gt\":3},\"text\":\"{dayRisk:1}R is past your plan's daily limit of −3R. Today's maximum can be lower than the limit, never higher.\"},{\"when\":{\"all\":[{\"field\":\"fit\",\"lt\":3},{\"field\":\"dayRisk\",\"gt\":1.5}]},\"text\":\"A readiness check failed, so the plan cuts risk: at most half the daily limit, 1.5R, or the simulator only.\"}],\"correct\":\"Saved as today's session start. The CPI scenario matters most: it decides what you do from 15:15 until the spread is normal again.\",\"concept\":\"pre-market-routine\"}],\"check\":[\"q-2.13.3-1\",\"q-2.13.3-2\",\"q-2.13.3-3\"],\"recap\":{\"takeaways\":[\"Run the same routine every session: readiness, overnight, calendar, regime, levels, scenarios, watchlist, risk.\",\"The routine's job is to catch today's event or limit before the first order.\",\"End it in writing, with two or three if-then scenarios, one for every scheduled release.\"],\"next\":\"Next, 2.13.4: if-then plans, turning the routine's scenarios into rules with one trigger and one action each.\"}},\"2.13.4\":{\"unit\":\"2.13\",\"courseId\":\"2.13.4\",\"bridge\":\"2.13.3's routine ended with if-then scenarios. In 1.7.6 you wrote such rules for urges, and in 2.12.7 guard-rails against tilt. Here the rules cover the whole session, market events and your own states, and you count how often you followed them.\",\"hook\":{\"prompt\":\"Which plan is easier to follow under pressure? A: 'Be careful around news.' B: 'If a red event is within 15 minutes, then I place no new orders.'\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"A\",\"feedback\":\"'Careful' leaves every decision to the moment, which is exactly when judgement is weakest.\"},{\"id\":\"b\",\"label\":\"B\",\"feedback\":\"Right: a time you can see on the calendar and an action you can check. Nothing is left to decide.\"}],\"answer\":\"b\"},\"compare\":\"You chose “{yours}”. B holds under pressure: the trigger is on the calendar and the action is already decided. 'Careful' gets decided in the moment.\",\"concept\":\"if-then-rules\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"Decide before, act on cue\",\"text\":\"In 1.7 you wrote [[if-then-rule|if-then rules]] for urges. Here they cover the whole session: **market triggers**, such as a price, a time, an event or a count, and **state triggers**, such as two losses in a row or a check-in of 4 of 5. Studies outside trading find these plans help people act as intended. Evidence grade B.\"},{\"kind\":\"match\",\"title\":\"Vague to if-then\",\"prompt\":\"Each vague intention needs one observable trigger and one action. Match it to its if-then version.\",\"columns\":[\"Vague\",\"If-then\"],\"pairs\":[{\"left\":\"Don't chase\",\"right\":\"If price is more than 2 ATR above the 20 EMA, then I wait for a pullback\",\"wrong\":\"Chasing is buying far from value: the trigger measures that distance.\"},{\"left\":\"Control your losses\",\"right\":\"If I lose two trades in a row, then I pause for 15 minutes\",\"wrong\":\"Losses in a row are a count you can see. The action is a timed pause.\"},{\"left\":\"Respect the range\",\"right\":\"If a candle closes outside the range, then I stop range trading and switch to the breakout card\",\"wrong\":\"A range is respected until a close outside it. That close is the trigger.\"},{\"left\":\"Stay out of messy markets\",\"right\":\"If my regime label is 'unclear', then I trade no card that needs a trend\",\"wrong\":\"'Messy' needs the routine's regime label to become observable.\"}],\"correct\":\"Each rule has a trigger anyone could see and one action you can check afterwards.\",\"concept\":\"if-then-rules\"},{\"kind\":\"worked\",\"title\":\"From scenarios to rules\",\"lines\":[\"Bullish: if two candles close above 60.50, then I buy near 60.80, stop 59.90, target 62.60.\",\"False breakout: if one candle closes above 60.50 and the next closes back inside, then no entry.\",\"Bearish: if a candle closes below 59.00, then I drop the long idea.\",\"Sideways: if price stays between 59.00 and 60.50, then I wait.\",\"Rules that end in no new order: ?\"],\"ask\":{\"answer\":3,\"tolerance\":0,\"feedback\":[{\"value\":1,\"text\":\"That's the rule that places an order. Count the others: no entry, drop the idea, wait.\"},{\"value\":4,\"text\":\"The bullish rule does place an order. The other three don't.\"}],\"correct\":\"Right: three of four. Most if-then rules stop you acting; few tell you to act.\"},\"after\":\"Written this way, the scenario plan from 2.13.1 becomes four rules you can mark after the session: fired or not, followed or not.\",\"concept\":\"scenario-planning\"},{\"kind\":\"figure\",\"title\":\"After the session\",\"text\":\"Tuesday's five rules, marked after the session. Adherence counts only the rules that fired.\",\"figure\":{\"kind\":\"flow\",\"start\":\"r1\",\"nodes\":[{\"id\":\"r1\",\"text\":\"If a red event is within 15 minutes, no new orders: fired, followed\",\"kind\":\"end\"},{\"id\":\"r2\",\"text\":\"If two candles close above 60.50, buy near 60.80: didn't fire\",\"kind\":\"end\"},{\"id\":\"r3\",\"text\":\"If I lose two in a row, pause 15 minutes: fired, not followed\",\"kind\":\"end\"},{\"id\":\"r4\",\"text\":\"If price is 2 ATR above the 20 EMA, wait: fired, followed\",\"kind\":\"end\"},{\"id\":\"r5\",\"text\":\"If my check-in is 4 of 5, half size: fired, followed\",\"kind\":\"end\"}],\"steps\":[\"Five rules written before the session. One never fired.\",\"Four fired. Three were followed; the pause after two losses wasn't.\",\"Adherence = followed ÷ fired = 3 ÷ 4 = 75%.\"]},\"concept\":\"if-then-rules\"},{\"kind\":\"predict\",\"title\":\"Fired, not followed\",\"prompt\":\"The pause rule fired after two losses, and you traded again five minutes later. What goes in the journal?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"nothing\",\"label\":\"Nothing: the next trade won\",\"feedback\":\"The outcome doesn't erase the break. A rule broken on a winning trade is still broken.\"},{\"id\":\"tag\",\"label\":\"The error tag, and the rule that fired\",\"feedback\":\"Right. Tag the break and name the rule, so both can be counted.\"},{\"id\":\"delete\",\"label\":\"Delete the rule: it doesn't suit you\",\"feedback\":\"One break isn't evidence against a rule. Rules change only through your plan's rule for changes.\"}],\"answer\":\"tag\"},\"reveal\":\"Log the [[error-tag|error tag]] and the rule that fired. Over a month, adherence by rule shows which rules you keep and which need a [[guard-rail]], such as a pause timer the app enforces.\",\"concept\":\"if-then-rules\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"A rule that never fires costs nothing. A rule that fires and isn't followed is your next process goal. Track adherence: followed ÷ fired.\"},{\"kind\":\"fields\",\"title\":\"Your if-then rules\",\"prompt\":\"Write two rules for your next session: one for a market event and one for your own state. One observable trigger and one action each.\",\"fields\":[{\"id\":\"market\",\"label\":\"If [market trigger], then [one action]\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. If a red event is within 15 minutes, then I place no new orders\",\"required\":true},{\"id\":\"state\",\"label\":\"If [your state], then [one action]\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. If I lose two trades in a row, then I pause for 15 minutes\",\"required\":true}],\"correct\":\"Saved for your next session. Afterwards, mark each one: fired or not, followed or not.\",\"concept\":\"if-then-rules\"}],\"task\":{\"widget\":\"bias-spotter\",\"data\":{\"cards\":[{\"id\":\"r1\",\"text\":\"'Don't overtrade' became: If I've taken three trades today, then I place no more orders until tomorrow.\",\"answer\":\"ok\",\"correct\":\"Valid. A count anyone can check, and one action: no more orders today.\",\"rationales\":{\"trigger\":\"Three trades is a count on your ticket history. Two people would always agree on it.\",\"action\":\"'No more orders until tomorrow' is easy to check afterwards: the log shows any fourth order.\",\"open\":\"Nothing is left to decide: after the third trade, there is only one thing to do.\"}},{\"id\":\"r2\",\"text\":\"'Avoid bad days' became: If I feel off, then I trade at half size.\",\"answer\":\"trigger\",\"correct\":\"Trigger you can't observe. 'Feel off' needs a test, such as less than six hours' sleep or a check-in of 4 of 5.\",\"rationales\":{\"ok\":\"Half size is a clear action, but 'feel off' can be argued either way, exactly when it matters.\",\"action\":\"The action is fine: half size can be checked on every ticket. The trigger is the vague part.\",\"open\":\"The action is a single one. The problem is knowing when the rule fires.\"}},{\"id\":\"r3\",\"text\":\"'Handle news' became: If a red event is within 15 minutes, then I'll be extra careful.\",\"answer\":\"action\",\"correct\":\"No action you can check. 'Extra careful' could mean anything. Try: 'then I place no new orders until the spread is back to normal.'\",\"rationales\":{\"ok\":\"The trigger is a time on the calendar, but nobody could check afterwards whether you were 'careful'.\",\"trigger\":\"A red event within 15 minutes is on the calendar for anyone to see. The trigger is fine.\",\"open\":\"There's no choice between actions here. There's no real action at all.\"}},{\"id\":\"r4\",\"text\":\"'Manage winners' became: If price reaches 2R, then I either take profit or trail the stop.\",\"answer\":\"open\",\"correct\":\"Leaves the choice open. Both actions are fine on their own, but 'either … or' hands the decision back to the moment. Pick one.\",\"rationales\":{\"ok\":\"The trigger is clear, but the rule doesn't say which action. You'd decide at 2R, under pressure.\",\"trigger\":\"Reaching 2R is a price anyone can see. The trigger isn't the problem.\",\"action\":\"Each action can be checked. The problem is that there are two, and the choice is made later.\"}},{\"id\":\"r5\",\"text\":\"'Respect my stop' became: If price comes within 0.10 of my stop, then I leave the stop where it is.\",\"answer\":\"ok\",\"correct\":\"Valid. A distance anyone can measure, and one action: leave the stop. The log shows whether it moved.\",\"rationales\":{\"trigger\":\"0.10 from the stop is a measured distance. Two people watching the same chart would agree.\",\"action\":\"Leaving the stop in place can be checked from the order log: it either moved or it didn't.\",\"open\":\"There's only one action, so nothing is left to decide when price comes close.\"}}],\"options\":[{\"id\":\"ok\",\"label\":\"Valid: one trigger, one action\"},{\"id\":\"trigger\",\"label\":\"Trigger you can't observe\"},{\"id\":\"action\",\"label\":\"No action you can check\"},{\"id\":\"open\",\"label\":\"Leaves the choice open\"}]},\"goal\":\"Five vague rules, each rewritten by a trader. Check each rewrite: one observable trigger and one action, with nothing left to decide in the moment.\",\"success\":{\"field\":\"solved\",\"eq\":5},\"correct\":\"Five rewrites checked, two valid. The others leave a feeling, a vague action or a choice to the moment, which is what the rule was meant to remove.\",\"hints\":[\"Trigger test: could two people watching the same screen agree it happened?\",\"Action test: is there exactly one thing to do, and could you check later that you did it?\",\"'Either … or' means the decision is still waiting for the moment.\"],\"showMe\":{\"solved\":5},\"concept\":\"if-then-rules\"},\"check\":[\"q-2.13.4-1\",\"q-2.13.4-2\",\"q-2.13.4-3\"],\"recap\":{\"takeaways\":[\"An if-then rule has one observable trigger and one action, so nothing is left to decide.\",\"Write rules for market events and for your own states, such as two losses in a row.\",\"After each session, mark rules fired and followed. Adherence = followed ÷ fired.\"],\"next\":\"Next, 2.13.5: the error taxonomy, a fixed list of codes for the rules you didn't follow, each priced in R.\"}},\"2.13.5\":{\"unit\":\"2.13\",\"courseId\":\"2.13.5\",\"bridge\":\"In 2.13.4 you counted rules fired but not followed. Each costs something. In 1.6.6 you sorted mistakes from variance; here every mistake gets a code from a fixed list and a price in R, so 2.12's biases show up as numbers you can rank.\",\"hook\":{\"prompt\":\"This month: 40 trades, net −3.0R. Trades tagged 'stop widened' cost −6.4R compared with the same trades done by the rules. What would the month have been without that one error?\",\"control\":{\"kind\":\"slider\",\"min\":-5,\"max\":5,\"step\":0.1,\"unit\":\"R\",\"start\":0,\"answer\":3.4,\"tolerance\":0.2,\"feedback\":[{\"from\":-5,\"to\":3.1,\"text\":\"Higher than that. Remove the error's cost: −3.0 − (−6.4) = +3.4R.\"},{\"from\":3.7,\"to\":5,\"text\":\"A little lower: −3.0 + 6.4 = +3.4R.\"}]},\"compare\":\"You said {yours}. Without the stop widening: −3.0 − (−6.4) = +3.4R. One error turned a winning month into a losing one.\",\"concept\":\"error-taxonomy\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"A fixed list\",\"text\":\"In 1.6 you named mistakes with the app's [[error-tag|error tags]]. Level 2 uses a fixed list of codes, so a month can be counted, not just remembered: E-SETUP, E-SIZE, E-STOP-NONE, E-STOP-WIDEN, E-EXIT-EARLY, E-EXIT-LATE, E-AVG-DOWN, E-REVENGE, E-LIMIT, E-EVENT, E-HEAT, E-CHASE, E-JOURNAL. Free text like 'bad trade' can't be added up.\"},{\"kind\":\"match\",\"title\":\"Journal line to tag\",\"prompt\":\"Each journal line gets one code. Match them.\",\"columns\":[\"Journal line\",\"Tag\"],\"pairs\":[{\"left\":\"Bought a breakout that isn't on any card\",\"right\":\"E-SETUP\",\"wrong\":\"No card allows the trade at all: the setup itself is the error.\"},{\"left\":\"Risked 1.3% where the plan says 1%\",\"right\":\"E-SIZE\",\"wrong\":\"1.3% is 30% over plan, past the 10% tolerance: a size error.\"},{\"left\":\"Moved the stop from 56.40 to 55.60 as price came close\",\"right\":\"E-STOP-WIDEN\",\"wrong\":\"The stop moved away from price, raising the risk.\"},{\"left\":\"Closed at +0.5R on one red candle; the plan held to 2R\",\"right\":\"E-EXIT-EARLY\",\"wrong\":\"The exit came before the plan's target, on a single candle.\"},{\"left\":\"Entered three minutes before a red release\",\"right\":\"E-EVENT\",\"wrong\":\"The timing broke a no-trade condition around a scheduled event.\"},{\"left\":\"Bought 2.5 ATR above the 20 EMA after a fast run\",\"right\":\"E-CHASE\",\"wrong\":\"Buying far from value after a run is chasing.\"}],\"correct\":\"Six lines, six codes. Some already exist in your debrief under long names: E-STOP-WIDEN is 'Moving the stop further away', E-CHASE is 'Chasing extended moves'.\",\"concept\":\"error-taxonomy\"},{\"kind\":\"worked\",\"title\":\"Price one error\",\"lines\":[\"Entry 57.20, planned stop 56.40: 1R is 0.80 a unit.\",\"The stop was moved to 55.60 and hit: 1.60 a unit, or −2.0R.\",\"By the rules, the stop at 56.40 would have cost −1.0R.\",\"Error cost = −2.0 − (−1.0) = ?\"],\"ask\":{\"answer\":-1,\"tolerance\":0,\"unit\":\"R\",\"feedback\":[{\"value\":-2,\"text\":\"That's the whole loss. Take away what the rules would have lost anyway: −1.0R.\"},{\"value\":1,\"text\":\"Right size, but it's a cost: write it as −1.0.\"}],\"correct\":\"Right: −1.0R. [[error-cost|Error cost]] compares a trade with the same trade done by the rules, not with a perfect trade.\"},\"after\":\"Add up a month of these and you get the hook: −6.4R of stop widening, against a month of −3.0R. A stop hit at −1R by the rules costs nothing: that's variance.\",\"concept\":\"error-taxonomy\"},{\"kind\":\"figure\",\"title\":\"The month's Pareto\",\"text\":\"The same month: every error cost added up by tag and sorted, biggest first.\",\"figure\":{\"kind\":\"bars\",\"unit\":\"R\",\"bars\":[{\"label\":\"E-STOP-WIDEN\",\"value\":-6.4},{\"label\":\"E-CHASE\",\"value\":-2.1},{\"label\":\"E-EXIT-EARLY\",\"value\":-1.3},{\"label\":\"E-SIZE\",\"value\":-0.8},{\"label\":\"E-EVENT\",\"value\":-0.6}],\"steps\":[\"Five tags cost −11.2R in total this month.\",\"E-STOP-WIDEN alone is −6.4R, more than half of it.\"]},\"concept\":\"error-taxonomy\"},{\"kind\":\"match\",\"title\":\"Mistake or variance?\",\"prompt\":\"Six losing trades. Sort each into Mistake, which gets a tag, or Variance, which you accept.\",\"pairs\":[{\"left\":\"Every rule followed; stopped at −1.0R, then price ran to the target\",\"right\":\"Variance\",\"wrong\":\"Every rule was followed. What price did after the exit doesn't make it a mistake.\"},{\"left\":\"Entered 5 minutes before a red release; the spread jumped; −1.6R\",\"right\":\"Mistake\",\"wrong\":\"The card's no-trade window around red events was broken. That's E-EVENT.\"},{\"left\":\"Gap through the stop overnight, no event due, sized at 1%: −1.3R\",\"right\":\"Variance\",\"wrong\":\"Size and stop were right, and nothing was due. The gap is the market.\"},{\"left\":\"Stop moved down as price came close; −2.0R\",\"right\":\"Mistake\",\"wrong\":\"Moving the stop away broke the plan: E-STOP-WIDEN.\"},{\"left\":\"Fourth stop-out in a row on a valid card, −1.0R each\",\"right\":\"Variance\",\"wrong\":\"A streak with every rule followed is variance, however it feels.\"},{\"left\":\"Risked 1.5% after two losses 'to get it back'; −1.5R\",\"right\":\"Mistake\",\"wrong\":\"Sizing up after losses breaks the risk rule: E-REVENGE.\"}],\"correct\":\"Three each. The test is the plan, not the result: a −1.3R gap at the right size is variance; a −1.6R release trade is a mistake.\",\"concept\":\"mistake-vs-variance\"},{\"kind\":\"predict\",\"title\":\"One drill\",\"prompt\":\"From the month's Pareto, which drill do you start with?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"widen\",\"label\":\"Stops are placed with the order and never edited after entry\",\"feedback\":\"Right. It targets −6.4R, more than half of the month's error cost.\"},{\"id\":\"chase\",\"label\":\"Enter only at the card's level, never after a run\",\"feedback\":\"A good drill, but it targets −2.1R. The biggest bar is the stop widening.\"},{\"id\":\"all\",\"label\":\"All five at once\",\"feedback\":\"Five drills at once means none gets your full attention. Start with the biggest bar.\"}],\"answer\":\"widen\"},\"reveal\":\"One drill, aimed at the biggest bar. Next month's Pareto shows whether it worked: the E-STOP-WIDEN bar should shrink, whatever the month's profit.\",\"concept\":\"error-taxonomy\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"**Fix the biggest bar first.** Mistakes get a tag, a cost and a drill. Variance gets nothing: no tag, no drill, no rule change.\"}],\"task\":{\"widget\":\"bias-spotter\",\"data\":{\"cards\":[{\"id\":\"t1\",\"text\":\"Pullback card, every condition met, stop kept at 56.40. Stopped out: −1.0R.\",\"answer\":\"clean\",\"correct\":\"Clean. A valid trade that lost: variance, error cost 0.\",\"rationales\":{\"widen\":\"The stop stayed at 56.40, where the card put it.\",\"chase\":\"The entry came from the card's trigger, not from a run.\",\"size\":\"Nothing says the size was off. A −1.0R loss is exactly the planned risk.\",\"event\":\"No release is mentioned, and every condition was met.\",\"early\":\"The trade was stopped out, not closed by hand.\"}},{\"id\":\"t2\",\"text\":\"Stop moved from 56.40 to 55.60 as price came close. Stopped at 55.60: −2.0R.\",\"answer\":\"widen\",\"correct\":\"E-STOP-WIDEN. By the rules: −1.0R. Error cost: −1.0R.\",\"rationales\":{\"clean\":\"The card put the stop at 56.40. Moving it away doubled the loss, so a rule broke.\",\"chase\":\"The entry isn't the problem here. Look at what happened to the stop.\",\"size\":\"The size didn't change; the distance to the stop did.\",\"event\":\"No release is involved. The stop was moved by hand.\",\"early\":\"Nothing was closed early. The loss grew because the stop moved away.\"}},{\"id\":\"t3\",\"text\":\"Bought after a three-candle run, 2.5 ATR above the 20 EMA. No card allows it. Stopped: −1.0R.\",\"answer\":\"chase\",\"correct\":\"E-CHASE. By the rules: no trade, 0R. Error cost: −1.0R.\",\"rationales\":{\"clean\":\"No card allows this entry, so the whole loss comes from the process.\",\"widen\":\"The stop wasn't moved. The problem was buying after the run.\",\"size\":\"The size was normal. The entry itself broke the plan.\",\"event\":\"No release is mentioned. The entry came after a fast run.\",\"early\":\"It was stopped, not closed early. Look at where it was bought.\"}},{\"id\":\"t4\",\"text\":\"Valid card, but sized at 1.4% of equity instead of 1%. Stopped: −1.4R.\",\"answer\":\"size\",\"correct\":\"E-SIZE: 40% over plan, past the 10% tolerance. By the rules: −1.0R. Error cost: −0.4R.\",\"rationales\":{\"clean\":\"The card was valid, but 1.4% is 40% more risk than planned. That's a process error.\",\"widen\":\"The stop was kept. The extra loss came from the size.\",\"chase\":\"The setup was valid. Only the size broke the plan.\",\"event\":\"No release is involved. Compare the risk with the plan's 1%.\",\"early\":\"Nothing was closed early. The loss is bigger because the position was.\"}},{\"id\":\"t5\",\"text\":\"Entered 5 minutes before a red release. The spread jumped and the stop filled at −1.6R.\",\"answer\":\"event\",\"correct\":\"E-EVENT. The card says no trade within 15 minutes of a red event: 0R. Error cost: −1.6R.\",\"rationales\":{\"clean\":\"The card's no-trade condition covers a red event within 15 minutes. Entering broke it.\",\"widen\":\"The stop wasn't moved: it filled past its price because the spread jumped at the release.\",\"chase\":\"The problem isn't a run before entry, it's the timing: five minutes before a release.\",\"size\":\"Sized normally. The loss grew because the stop filled past its price at the release.\",\"early\":\"It wasn't closed by hand. The release did the damage.\"}},{\"id\":\"t6\",\"text\":\"Closed at +0.5R on one red candle. The plan's 2R target was hit two hours later.\",\"answer\":\"early\",\"correct\":\"E-EXIT-EARLY. By the rules: +2.0R. Error cost: −1.5R.\",\"rationales\":{\"clean\":\"It made money, but the plan held to 2R. A profitable trade can still break a rule.\",\"widen\":\"The stop wasn't touched. Look at how the trade ended.\",\"chase\":\"The entry was fine. The exit broke the plan.\",\"size\":\"The size was normal. The plan was broken on the way out.\",\"event\":\"No release is mentioned. A single red candle ended the trade.\"}},{\"id\":\"t7\",\"text\":\"Price gapped through the stop overnight, with nothing on the calendar. Sized at 1%: −1.3R.\",\"answer\":\"clean\",\"correct\":\"Clean. Right size, right stop, no event due: the gap is the market. Variance, error cost 0.\",\"rationales\":{\"widen\":\"The stop stayed put; price jumped past it while the market was shut.\",\"chase\":\"Nothing says the entry chased a run.\",\"size\":\"Sized at 1%, as planned. The extra 0.3R came from the gap, not the size.\",\"event\":\"Nothing was on the calendar, so no no-trade condition was broken.\",\"early\":\"The trade wasn't closed by hand. The gap filled the stop.\"}},{\"id\":\"t8\",\"text\":\"Valid card, target hit: +2.0R.\",\"answer\":\"clean\",\"correct\":\"Clean. A winner by the rules: error cost 0.\",\"rationales\":{\"widen\":\"The stop was never touched.\",\"chase\":\"The entry came from a valid card.\",\"size\":\"Nothing says the size was off.\",\"event\":\"No release is mentioned.\",\"early\":\"It ran to the plan's target, not closed early.\"}}],\"options\":[{\"id\":\"clean\",\"label\":\"Clean\"},{\"id\":\"widen\",\"label\":\"E-STOP-WIDEN\"},{\"id\":\"chase\",\"label\":\"E-CHASE\"},{\"id\":\"size\",\"label\":\"E-SIZE\"},{\"id\":\"event\",\"label\":\"E-EVENT\"},{\"id\":\"early\",\"label\":\"E-EXIT-EARLY\"}]},\"goal\":\"Eight trades from one week. Tag each with its error code, or mark it Clean if every rule was followed. Each trade's error cost appears when you answer.\",\"success\":{\"field\":\"solved\",\"eq\":8},\"correct\":\"All eight tagged: five errors, three clean. Total error cost: −5.5R, with E-EVENT the biggest at −1.6R. That's this week's drill.\",\"hints\":[\"First ask: was every rule followed? If yes, it's Clean, whatever the result.\",\"If not, name the one rule that broke: entry, size, stop, timing or exit.\",\"Error cost = result as traded − result by the rules.\"],\"showMe\":{\"solved\":8},\"concept\":\"error-taxonomy\"},\"check\":[\"q-2.13.5-1\",\"q-2.13.5-2\",\"q-2.13.5-3\"],\"recap\":{\"takeaways\":[\"Tag every process error from the same fixed list, so a month of errors can be counted.\",\"Error cost = result as traded minus the same trade done by the rules, in R.\",\"Mistakes get a tag and a drill; variance gets nothing. Fix the biggest bar first.\"],\"next\":\"Next, 2.13.6: daily and weekly reviews, where the tags and their costs become one process goal for next week.\"}},\"2.13.6\":{\"unit\":\"2.13\",\"courseId\":\"2.13.6\",\"bridge\":\"In 2.13.5 you priced a month of errors. The reviews are where that happens. They extend 1.6.5's decision review: daily in minutes, weekly by setup, time and error tag, with 2.11.6's metrics, ending in one process goal.\",\"hook\":{\"prompt\":\"Monday's best trade made +2.6R. The best decision of the day was skipping a trade that would have broken your rules. Which goes in the review as 'best'?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"trade\",\"label\":\"The +2.6R trade\",\"feedback\":\"It made the most, but a profit says little about the decision behind it. The review grades decisions.\"},{\"id\":\"skip\",\"label\":\"The skipped trade\",\"feedback\":\"Right. Skipping a trade that broke your rules was the day's best decision, even though it paid nothing.\"}],\"answer\":\"skip\"},\"compare\":\"You chose “{yours}”. The review's 'best' is a decision: the skipped trade kept a rule. A +2.6R result can come from a sound decision or a lucky one.\",\"concept\":\"trading-reviews\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"The daily report\",\"text\":\"The simulator writes most of your [[daily-review|daily review]]: trades, rules followed, error tags, risk used. Your part takes five to ten minutes and grades **decisions**, not profit: the best and the worst of the day, each loss sorted as mistake or variance, and one lesson for tomorrow.\"},{\"kind\":\"order\",\"title\":\"The daily review\",\"prompt\":\"Put the daily review in order. Then write the lesson from your last session, real or simulated.\",\"items\":[\"Read the day's process KPIs\",\"Name the best and the worst decision\",\"Sort each loss: mistake or variance\",\"Write one lesson\",\"Prepare tomorrow: put the lesson into the routine\"],\"wrong\":\"Start from the facts the simulator logged, and end with tomorrow. The lesson comes after the losses are sorted.\",\"explain\":\"Facts, then decisions, then losses, then one lesson, then tomorrow. Grading decisions before you dwell on the profit keeps the result from grading them for you.\",\"note\":{\"key\":\"2.13.6:lesson\",\"label\":\"The lesson from your last session (optional)\",\"placeholder\":\"e.g. I skipped the routine on Tuesday and entered 5 minutes before a release.\"},\"concept\":\"trading-reviews\"},{\"kind\":\"explain\",\"title\":\"The weekly review\",\"text\":\"Once a week, the [[weekly-review|weekly review]] slices your trades by setup, time of day, instrument and error tag, and sets your equity curve against the range your [[expectancy]] predicts. It ends with **one process goal**, taken from the costliest error, and a short note of what went well, so good habits get written down too.\"},{\"kind\":\"figure\",\"title\":\"The week by error\",\"text\":\"A synthetic week of 25 trades: error cost by tag and time of day, biggest first.\",\"figure\":{\"kind\":\"bars\",\"unit\":\"R\",\"bars\":[{\"label\":\"E-CHASE, first 30 min\",\"value\":-2.4},{\"label\":\"E-EXIT-EARLY\",\"value\":-0.9},{\"label\":\"E-STOP-WIDEN\",\"value\":-0.5},{\"label\":\"E-CHASE, later\",\"value\":-0.3},{\"label\":\"E-SIZE\",\"value\":-0.2}],\"steps\":[\"Total error cost this week: −4.3R.\",\"Chasing in the first 30 minutes alone: −2.4R, more than half.\"]},\"concept\":\"trading-reviews\"},{\"kind\":\"reveal\",\"title\":\"Blind replay\",\"prompt\":\"In a [[blind-replay|blind replay]], the chart stops at the decision point. Monday's pullback card: buy stop 57.20, stop 56.40, target 59.60. Place the order?\",\"chart\":{\"candles\":[{\"o\":54,\"h\":54.45,\"l\":53.8,\"c\":54.3},{\"o\":54.3,\"h\":55.05,\"l\":54.2,\"c\":54.9},{\"o\":54.9,\"h\":55.6,\"l\":54.75,\"c\":55.45},{\"o\":55.45,\"h\":56.15,\"l\":55.3,\"c\":56},{\"o\":56,\"h\":56.6,\"l\":55.85,\"c\":56.2},{\"o\":56.2,\"h\":56.35,\"l\":55.55,\"c\":55.7},{\"o\":55.7,\"h\":56.1,\"l\":55.4,\"c\":55.6},{\"o\":55.6,\"h\":56.35,\"l\":55.5,\"c\":56.15},{\"o\":56.15,\"h\":56.9,\"l\":56.05,\"c\":56.8},{\"o\":56.8,\"h\":57.55,\"l\":56.7,\"c\":57.45},{\"o\":57.45,\"h\":58.2,\"l\":57.3,\"c\":58.05},{\"o\":58.05,\"h\":58.75,\"l\":57.9,\"c\":58.6},{\"o\":58.6,\"h\":59.3,\"l\":58.3,\"c\":59.15},{\"o\":59.15,\"h\":59.6,\"l\":58.8,\"c\":59.3},{\"o\":59.3,\"h\":59.4,\"l\":58.6,\"c\":58.7},{\"o\":58.7,\"h\":58.85,\"l\":58.05,\"c\":58.15},{\"o\":58.15,\"h\":58.3,\"l\":57.5,\"c\":57.6},{\"o\":57.6,\"h\":57.75,\"l\":56.95,\"c\":57.15},{\"o\":57.15,\"h\":57.2,\"l\":56.8,\"c\":57.1},{\"o\":57.1,\"h\":57.55,\"l\":57,\"c\":57.45},{\"o\":57.45,\"h\":57.7,\"l\":57.25,\"c\":57.35},{\"o\":57.35,\"h\":57.4,\"l\":56.85,\"c\":56.95},{\"o\":56.95,\"h\":57.1,\"l\":56.6,\"c\":56.7},{\"o\":56.7,\"h\":56.75,\"l\":56.2,\"c\":56.3},{\"o\":56.3,\"h\":56.55,\"l\":56.05,\"c\":56.45},{\"o\":56.45,\"h\":56.9,\"l\":56.4,\"c\":56.8}],\"visible\":19,\"layers\":[{\"kind\":\"level\",\"price\":57.2,\"role\":\"entry\",\"label\":\"Buy stop 57.20\"},{\"kind\":\"level\",\"price\":56.4,\"role\":\"stop\",\"label\":\"Stop 56.40\"},{\"kind\":\"level\",\"price\":59.6,\"role\":\"target\",\"label\":\"Target 59.60\"}]},\"choices\":[{\"id\":\"place\",\"label\":\"Place it: every condition is met\"},{\"id\":\"skip\",\"label\":\"Skip it\",\"feedback\":\"Check the card: higher swing highs and lows, the pullback held above 55.40, and 3.0R to the target. Every condition is met.\"}],\"answer\":\"place\",\"after\":\"Filled at 57.20, then stopped at 56.40: −1R. Blind, the decision met every condition: a good decision with a bad outcome. Shown the loss first, it's easy to find a flaw that was never on the screen.\",\"concept\":\"hindsight-bias\"},{\"kind\":\"predict\",\"title\":\"One goal\",\"prompt\":\"From the week's error costs, pick next week's single process goal.\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"profit\",\"label\":\"Make +5R next week\",\"feedback\":\"An outcome goal: luck decides much of one week, and chasing it pushes size up.\"},{\"id\":\"open\",\"label\":\"In the first 30 minutes, enter only at the card's level, never after a run\",\"feedback\":\"Right. It targets the biggest cost, −2.4R, and it's fully in your control.\"},{\"id\":\"hold\",\"label\":\"Hold every winner to its target\",\"feedback\":\"A process goal, but it targets −0.9R. The biggest cost this week is chasing at the open.\"},{\"id\":\"stops\",\"label\":\"Never widen a stop\",\"feedback\":\"A good rule, but it cost −0.5R this week. Start with the biggest bar.\"},{\"id\":\"winrate\",\"label\":\"Win 60% of trades\",\"feedback\":\"An outcome you don't control. A process goal names an action you can check.\"}],\"answer\":\"open\"},\"reveal\":\"One goal, from the biggest bar, worded as an action you can check every day. Next week's review then shows whether it worked.\",\"concept\":\"trading-reviews\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"Four weekly reviews in a row are part of the Level 2 gate. Review blind and grade decisions: [[hindsight-bias|hindsight bias]] is well documented (grade B), and it's how a valid loss becomes a 'mistake'.\"}],\"check\":[\"q-2.13.6-1\",\"q-2.13.6-2\",\"q-2.13.6-3\"],\"recap\":{\"takeaways\":[\"Daily: five to ten minutes grading decisions, sorting losses, writing one lesson, preparing tomorrow.\",\"Weekly: slice by setup, time and error tag; end with one process goal from the biggest cost.\",\"Replay blind: grade the decision on what you could see, not on the outcome.\"],\"next\":\"Next, 2.13.7: KPIs and goals, what to measure, what to aim for, and how to change a rule safely.\"}},\"2.13.7\":{\"unit\":\"2.13\",\"courseId\":\"2.13.7\",\"bridge\":\"In 2.13.6 each weekly review ended with one process goal. Here you choose what to measure: 1.6.7's process KPIs as the grade, 2.11.6's outcome metrics as diagnostics with 2.11.7's intervals, and a written process before any rule changes.\",\"hook\":{\"prompt\":\"Which goal can you fully control this week?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"r\",\"label\":\"Make +3R\",\"feedback\":\"The market decides much of one week's result. You can do everything right and miss it.\"},{\"id\":\"win\",\"label\":\"Win 60% of trades\",\"feedback\":\"Over a week's trades, the win rate swings with luck. You can't choose which trades win.\"},{\"id\":\"stop\",\"label\":\"Place every stop before entry\",\"feedback\":\"Right. It depends only on what you do, and every ticket shows whether you did it.\"}],\"answer\":\"stop\"},\"compare\":\"You picked “{yours}”. Only 'Place every stop before entry' is fully yours. +3R and a 60% win rate depend on what the market does.\",\"concept\":\"process-goals\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"A balanced set\",\"text\":\"Your dashboard has three kinds of [[kpi|KPIs]]. **Process** KPIs are the grade: plan adherence, risk accuracy, [[stop-integrity|stop integrity]], limits kept, routine done, journal complete, error cost. **Outcome** KPIs are diagnostics: expectancy, win rate, payoff, drawdown, shown with their interval and greyed out below 30 trades. **Behaviour** KPIs flag patterns: risk after a loss, revenge trades, tilt.\"},{\"kind\":\"match\",\"title\":\"Which kind?\",\"prompt\":\"Sort each KPI into its kind.\",\"columns\":[\"KPI\",\"Kind\"],\"pairs\":[{\"left\":\"Stop integrity\",\"right\":\"Process\",\"wrong\":\"A stop at entry, never widened, depends only on you: process.\"},{\"left\":\"Error cost in R\",\"right\":\"Process\",\"wrong\":\"Error cost counts rule breaks, priced in R. The breaks are yours: process.\"},{\"left\":\"Routine done, days of 5\",\"right\":\"Process\",\"wrong\":\"Running the routine is fully in your hands: process.\"},{\"left\":\"Win rate\",\"right\":\"Outcome\",\"wrong\":\"Which trades win is up to the market: outcome.\"},{\"left\":\"Maximum drawdown\",\"right\":\"Outcome\",\"wrong\":\"Drawdown is a result of many trades: outcome, read with its sample.\"},{\"left\":\"Expectancy\",\"right\":\"Outcome\",\"wrong\":\"Average R per trade is a result: outcome, with an interval.\"},{\"left\":\"Risk taken right after a loss\",\"right\":\"Behaviour\",\"wrong\":\"This watches a pattern in how you react: behaviour.\"},{\"left\":\"Revenge trades a month\",\"right\":\"Behaviour\",\"wrong\":\"Counting revenge trades flags a pattern before it grows: behaviour.\"}],\"correct\":\"Process KPIs grade you. Outcome KPIs need a sample before they mean much. Behaviour KPIs flag a pattern before it grows.\",\"concept\":\"process-kpis\"},{\"kind\":\"worked\",\"title\":\"Risk accuracy, finer\",\"lines\":[\"Level 1 counted trades within the limit. Level 2 scores how far each trade missed its planned risk.\",\"Planned risk 100.00. Actual: 92.00, 108.00 and 100.00.\",\"Misses: 8%, 8% and 0%. Average miss: 5.33%.\",\"Risk accuracy = 100% − 5.33% = ?\"],\"ask\":{\"answer\":94.7,\"tolerance\":0.05,\"unit\":\"%\",\"feedback\":[{\"value\":66.7,\"text\":\"That's the Level 1 count: two of three within the limit. Level 2 scores the size of each miss.\"},{\"value\":5.33,\"text\":\"That's the average miss. Accuracy is what's left: 100% minus it.\"}],\"correct\":\"Right: 94.7%. Under-risking counts as a miss too: 92.00 isn't the plan either.\"},\"after\":\"The discipline score works the same way: 3 rule breaks in 60 decisions is 57 ÷ 60 = 95%.\",\"concept\":\"process-kpis\"},{\"kind\":\"explain\",\"title\":\"Goals you control\",\"text\":\"A [[process-goal|process goal]] names an action you fully control: 'a stop before entry on 100% of trades'. An outcome goal, 'make 5% this month', depends on luck, and near the end of the month it pushes you toward bigger positions to catch up. Set goals on process; read outcomes over hundreds of trades.\"},{\"kind\":\"order\",\"title\":\"Changing a rule\",\"prompt\":\"A rule changes only through a written process. Put the steps in order. Then write one change you'd like to test.\",\"items\":[\"Write the idea down; don't act on it\",\"Turn it into a hypothesis you can test\",\"Set the evidence bar: 30 to 50 trades, or a test\",\"Test it in the simulator\",\"Adopt it as a new plan version\"],\"wrong\":\"Start by writing it down, not by changing anything. The evidence bar is set before the test.\",\"explain\":\"Idea, hypothesis, evidence bar, test, new version. The bar is set before the test, so the result can't move it.\",\"note\":{\"key\":\"2.13.7:rule\",\"label\":\"A rule you'd like to change, as a hypothesis (optional)\",\"placeholder\":\"e.g. A stop 0.75 ATR under the pullback low loses less to noise than 0.5 ATR.\"},\"concept\":\"rule-change-governance\"},{\"kind\":\"predict\",\"title\":\"After three losses\",\"prompt\":\"Your pullback card has lost three in a row, every rule followed. You want to widen its stop rule from 0.5 to 1 ATR. What now?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"now\",\"label\":\"Change it now: three losses show it's too tight\",\"feedback\":\"Three trades can't show that: a valid card often loses three in a row. Changing now tests nothing.\"},{\"id\":\"log\",\"label\":\"Log the idea, and test it once the evidence bar is set\",\"feedback\":\"Right. The idea is kept, and the rule changes only if a test supports it.\"},{\"id\":\"today\",\"label\":\"Widen it for today only\",\"feedback\":\"A change mid-session, after losses, is exactly what the process forbids. Today's trades would test nothing.\"}],\"answer\":\"log\"},\"reveal\":\"Write it as a hypothesis, 'a wider stop loses less to noise', set the bar (30 to 50 trades, or a simulator test), then decide. If it passes, it becomes a new plan version, with a fresh count.\",\"concept\":\"rule-change-governance\"},{\"kind\":\"fields\",\"title\":\"Next week's goals\",\"prompt\":\"Set three process goals for next week, each with a target the app can measure. Outcome targets don't belong here.\",\"fields\":[{\"id\":\"stops\",\"label\":\"Stop placed before entry on __% of trades\",\"kind\":\"choice\",\"options\":[80,90,95,100],\"unit\":\"%\",\"default\":90},{\"id\":\"accuracy\",\"label\":\"Risk accuracy at least __%\",\"kind\":\"stepper\",\"min\":80,\"max\":100,\"step\":1,\"unit\":\"%\",\"default\":85},{\"id\":\"routine\",\"label\":\"Pre-market routine on __ of 5 sessions\",\"kind\":\"stepper\",\"min\":0,\"max\":5,\"step\":1,\"default\":3},{\"id\":\"own\",\"label\":\"Your own process goal (optional)\",\"kind\":\"text\",\"default\":\"\",\"placeholder\":\"e.g. Journal every trade within 10 minutes\"}],\"valid\":{\"all\":[{\"field\":\"stops\",\"eq\":100},{\"field\":\"accuracy\",\"gte\":95},{\"field\":\"routine\",\"eq\":5}]},\"feedback\":[{\"when\":{\"field\":\"stops\",\"ne\":100},\"text\":\"A goal of {stops}% plans for trades without a stop. The rule is every trade, so the goal is 100%.\"},{\"when\":{\"field\":\"accuracy\",\"lt\":95},\"text\":\"{accuracy}% allows an average miss of over 5%. With the sizing tool, 95% or more is fully in your hands.\"},{\"when\":{\"field\":\"routine\",\"lt\":5},\"text\":\"The routine takes ten minutes and is fully yours. Planning {routine} of 5 is planning to skip it.\"}],\"correct\":\"Saved as next week's goals. Each one is a number the app measures, and each depends only on what you do.\",\"concept\":\"process-goals\"}],\"check\":[\"q-2.13.7-1\",\"q-2.13.7-2\",\"q-2.13.7-3\"],\"recap\":{\"takeaways\":[\"Process KPIs are the grade; outcome KPIs are diagnostics, read with their interval and sample size.\",\"Set weekly goals you fully control, each with a number the app can measure.\",\"Change a rule only through idea, hypothesis, evidence bar, test and a new plan version.\"],\"next\":\"Next: the 2.13 checkpoint. Then unit 2.14, Instruments I, where stocks, forex and CFDs change your sizing, costs and risk.\"}}}");
